import{_ as a,a0 as s,w as i,s as d,ao as p,I as o,x as e,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能 | LCTT x X-CMD","titleTemplate":false,"description":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS","title":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能","tag":"201410","desc":""},"relativePath":"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS.md","filePath":"[post].md"}'),C={name:"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS.md"};function u(g,t,c,L,T,x){const l=s("Link");return i(),d("div",null,[t[13]||(t[13]=p(`<h1 id="在rhel-centos-5-6下停用按下ctrl-alt-del-重启系统的功能" tabindex="-1">在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能 <a class="header-anchor" href="#在rhel-centos-5-6下停用按下ctrl-alt-del-重启系统的功能" aria-label="Permalink to “在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重启系统的功能”">​</a></h1><p>在Linux里，由于对安全的考虑，我们允许任何人按下<strong>Ctrl-Alt-Del</strong>来<strong>重启</strong>系统。但是在生产环境中，应该停用按下Ctrl-Alt-Del 重启系统的功能。</p><p>在这篇文章里，我们将要介绍如何在RHEL和CentOS下停用该热键。</p><h3 id="在rhel-5-x和centos-5-x下" tabindex="-1">在RHEL 5.X和CentOS 5.X下 <a class="header-anchor" href="#在rhel-5-x和centos-5-x下" aria-label="Permalink to “在RHEL 5.X和CentOS 5.X下”">​</a></h3><p>保护<strong>init</strong>进程免于<strong>Ctrl-Alt-Del</strong>,像下面一样编辑&#39;<strong>/etc/inittab</strong>&#39;里由&#39;<strong>ca::ctrlaltdel</strong>:&#39;开头的一行:</p><pre><code>[root@localhost ~]# cat /etc/inittab
# Trap CTRL-ALT-DELETE
#ca::ctrlaltdel:/sbin/shutdown -t3 -r now
</code></pre><p>我们还可以改变&#39;ca::ctrlaltdel:&#39;这行来输出日志 ,如果任何人想用该热键重启服务器,就会有日志,</p><pre><code>[root@localhost ~]# cat /etc/inittab
# Trap CTRL-ALT-DELETE
ca::ctrlaltdel:/bin/logger -p authpriv.warning -t init &quot;Console-invoked Ctrl-Alt-Del was ignored&quot;
</code></pre><h3 id="在rhel6-x和centos-6-x下" tabindex="-1">在RHEL6.X和CentOS 6.X下 <a class="header-anchor" href="#在rhel6-x和centos-6-x下" aria-label="Permalink to “在RHEL6.X和CentOS 6.X下”">​</a></h3><p>在RHEL6.X和CentOS 6.X下, 该热键的行为由&#39;<strong>/etc/init/control-alt-delete.conf</strong>&#39;控制.</p><p><strong>第一步</strong> 在变化之前，先用下列命令备份配置</p><pre><code>[root@localhost ~]# cp -v /etc/init/control-alt-delete.conf /etc/init/control-alt-delete.override
</code></pre><p><strong>第二步</strong>编辑文件，把&#39;exec /sbin/shutdown&#39;这一行用下方配置代替，这个配置会在每次按下Ctrl-Alt-Del 时输出日志:</p><pre><code>[root@localhost ~]# cat /etc/init/control-alt-delete.conf
exec /usr/bin/logger -p authpriv.notice -t init &quot;Ctrl-Alt-Del was pressed and ignored&quot; 
</code></pre><hr>`,15)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),r(l,{href:"http://www.linuxtechi.com/disable-reboot-using-ctrl-alt-del-keys/"},{default:n(()=>[...t[0]||(t[0]=[e("http://www.linuxtechi.com/disable-reboot-using-ctrl-alt-del-keys/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),r(l,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),r(l,{href:"https://github.com/2q1w2007"},{default:n(()=>[...t[3]||(t[3]=[e("2q1w2007",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),r(l,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const m=a(C,[["render",u]]);export{h as __pageData,m as default};
